import java.util.*;

class Solution {
  public List<Integer> largestDivisibleSubset(int[] nums) {
    Arrays.sort(nums);
    int n = nums.length, bestEnd = 0;
    int[] len = new int[n], prev = new int[n];
    for (int i = 0; i < n; i++) {
      len[i] = 1;
      prev[i] = -1;
      for (int j = 0; j < i; j++)
        if (nums[i] % nums[j] == 0 && len[j] + 1 > len[i]) {
          len[i] = len[j] + 1;
          prev[i] = j;
        }
      if (len[i] > len[bestEnd]) bestEnd = i;
    }
    List<Integer> res = new ArrayList<>();
    for (int i = bestEnd; i >= 0; i = prev[i]) res.add(nums[i]);
    return res;
  }
}
